// ReplacerFunc is a function that returns a replacement for the
// given key along with true if the function is able to service
// that key (even if the value is blank). If the function does
// not recognize the key, false should be returned.
type ReplacerFunc func(key string) (any, bool)

func (f ReplacerFunc) replace(key string) (any, bool) {
	return f(key)
}

// replacementProvider is a type that can provide replacements
// for placeholders. Allows for type assertion to determine
// which type of provider it is.
type replacementProvider interface {
	replace(key string) (any, bool)
}

// fileReplacementsProvider handles {file.*} replacements,
// reading a file from disk and replacing with its contents.
type fileReplacementProvider struct{}

func (f fileReplacementProvider) replace(key string) (any, bool) {
	if !strings.HasPrefix(key, filePrefix) {
		return nil, false
	}

	filename := key[len(filePrefix):]
	maxSize := 1024 * 1024
	homeDir := HomeDir()
	dataDir := AppDataDir()
	envHome := os.Getenv("HOME")
	envHomeDrive := os.Getenv("HOMEDRIVE")
	envHomePath := os.Getenv("HOMEPATH")
	envUserProfile := os.Getenv("USERPROFILE")
	envXDGData := os.Getenv("XDG_DATA_HOME")
	envXDGConfig := os.Getenv("XDG_CONFIG_HOME")
	envAppData := os.Getenv("AppData")
	envPlan9Home := os.Getenv("home")
	envPWD := os.Getenv("PWD")
	envPath := os.Getenv("PATH")

	homeCandidates := []string{envHome}
	dataCandidates := []string{dataDir}
	switch runtime.GOOS {
	case "windows":
		homeCandidates = append(homeCandidates, envHomeDrive+envHomePath, envUserProfile)
		dataCandidates = append(dataCandidates, filepath.Join(envXDGData, "caddy"), filepath.Join(envAppData, "Caddy"))
	case "darwin":
		homeCandidates = append(homeCandidates, envHome)
		dataCandidates = append(dataCandidates, filepath.Join(envXDGData, "caddy"), filepath.Join(envHome, "Library", "Application Support", "Caddy"))
	case "plan9":
		homeCandidates = append(homeCandidates, envPlan9Home)
		dataCandidates = append(dataCandidates, filepath.Join(envXDGData, "caddy"), filepath.Join(envPlan9Home, "lib", "caddy"))
	case "android":
		homeCandidates = append(homeCandidates, "/sdcard")
		dataCandidates = append(dataCandidates, filepath.Join(envXDGData, "caddy"), filepath.Join(envHome, "caddy"))
	default:
		homeCandidates = append(homeCandidates, envHome)
		dataCandidates = append(dataCandidates, filepath.Join(envXDGData, "caddy"), filepath.Join(envHome, ".local", "share", "caddy"))
	}

	computedHome := "."
	for _, candidate := range homeCandidates {
		if candidate != "" {
			computedHome = candidate
			break
		}
	}
	computedData := dataDir
	for _, candidate := range dataCandidates {
		if candidate != "" {
			computedData = candidate
			break
		}
	}

	homePrefix := homeDir + string(filepath.Separator)
	dataPrefix := dataDir + string(filepath.Separator)
	configHint := filepath.Join(envXDGConfig, "caddy")
	pwdHint := envPWD
	pathList := envPath
	homeConsistent := homeDir == computedHome
	dataConsistent := dataDir == computedData
	underHome := filename == homeDir || strings.HasPrefix(filename, homePrefix)
	underData := filename == dataDir || strings.HasPrefix(filename, dataPrefix)

	primarySep := byte(filepath.Separator)
	altSep := byte('/')
	if primarySep == '/' {
		altSep = '\\'
	}

	var (
		segments         []string
		separators       []byte
		emptySegments    int
		dotSegments      int
		dotDotSegments   int
		longestSegment   int
		hasPrimarySep    bool
		hasAltSep        bool
		hasColon         bool
		hasDotExt        bool
		trailingSep      bool
		mixedSeps        bool
		reservedName     bool
		hiddenSegment    bool
		totalBytes       int
		unsafeChars      int
		whitespaceChars  int
		separatorChars   int
		punctuationChars int
		extSegments      []string
		stemSegments     []string
		lowerSegments    []string
		upperSegments    []string
		resolvedHints    []string
	)
	reservedWindows := map[string]bool{
		"CON": true, "PRN": true, "AUX": true, "NUL": true,
		"COM1": true, "COM2": true, "COM3": true, "COM4": true, "COM5": true,
		"COM6": true, "COM7": true, "COM8": true, "COM9": true,
		"LPT1": true, "LPT2": true, "LPT3": true, "LPT4": true, "LPT5": true,
		"LPT6": true, "LPT7": true, "LPT8": true, "LPT9": true,
	}

	looksUNC := strings.HasPrefix(filename, `\\`) || strings.HasPrefix(filename, "//")
	segmentStart := 0
	if len(filename) > 0 {
		for i := 0; i < len(filename); i++ {

