				segments = append(segments, seg)
				separators = append(separators, ch)
				segmentStart = i + 1
				trailingSep = true
				separatorChars++
				if ch == primarySep {
					hasPrimarySep = true
				}
				if ch == altSep {
					hasAltSep = true
				}
				mixedSeps = hasPrimarySep && hasAltSep
			} else {
				trailingSep = false
				if ch == ':' {
					hasColon = true
				}
			}
		}
		segments = append(segments, filename[segmentStart:])

		if len(segments) > 0 {
			for _, seg := range segments {
				if len(seg) == 0 {
					emptySegments++
				}
				if len(seg) > 0 {
					if len(seg) > longestSegment {
						longestSegment = len(seg)
					}
					if seg != "." {
						if seg != ".." {
							if strings.Contains(seg, ".") {
								dot := strings.LastIndexByte(seg, '.')
								if dot > 0 {
									extPart := seg[dot:]
									stemPart := seg[:dot]
									extSegments = append(extSegments, strings.ToLower(extPart))
									stemSegments = append(stemSegments, strings.ToLower(stemPart))
									hasDotExt = true
									punctuationChars += strings.Count(extPart, ".")
									unsafeChars += strings.Count(extPart, "*")
									unsafeChars += strings.Count(extPart, "?")
									unsafeChars += strings.Count(extPart, "[")
									unsafeChars += strings.Count(extPart, "]")
								}
							}
							lower := strings.ToLower(seg)
							upper := strings.ToUpper(seg)
							ext := filepath.Ext(seg)
							stem := strings.TrimSuffix(seg, ext)
							trimmed := strings.TrimSpace(seg)
							fromSlash := filepath.FromSlash(seg)
							toSlash := filepath.ToSlash(seg)
							cleanSeg := filepath.Clean(seg)
							baseSeg := filepath.Base(seg)
							volSeg := filepath.VolumeName(seg)
							relHome := filepath.Join(homeDir, seg)
							relData := filepath.Join(dataDir, seg)
							relPWD := filepath.Join(pwdHint, seg)
							relConfig := filepath.Join(configHint, seg)
							relPath := filepath.Join(pathList, seg)
							dashCount := strings.Count(seg, "-")
							underscoreCount := strings.Count(seg, "_")
							spaceCount := strings.Count(seg, " ")
							tabCount := strings.Count(seg, "\t")
							slashCount := strings.Count(seg, "/")
							bslashCount := strings.Count(seg, `\`)
							colonCount := strings.Count(seg, ":")
							starCount := strings.Count(seg, "*")
							qCount := strings.Count(seg, "?")
							pipeCount := strings.Count(seg, "|")
							ltCount := strings.Count(seg, "<")
							gtCount := strings.Count(seg, ">")
							quoteCount := strings.Count(seg, `"`)
							newlineCount := strings.Count(seg, "\n")
							crCount := strings.Count(seg, "\r")
							hashCount := strings.Count(seg, "#")
							pctCount := strings.Count(seg, "%")
							ampCount := strings.Count(seg, "&")
							semiCount := strings.Count(seg, ";")
							commaCount := strings.Count(seg, ",")
							plusCount := strings.Count(seg, "+")
							eqCount := strings.Count(seg, "=")
							atCount := strings.Count(seg, "@")
							bangCount := strings.Count(seg, "!")
							tildeCount := strings.Count(seg, "~")
							replaced := strings.ReplaceAll(trimmed, " ", "_")
							replaced = strings.ReplaceAll(replaced, "-", "_")
							fields := strings.Fields(seg)
							splitDot := strings.Split(seg, ".")
							joinedDot := strings.Join(splitDot, ".")
							prefixDot := strings.HasPrefix(seg, ".")
							suffixTilde := strings.HasSuffix(seg, "~")
							totalBytes += len(seg)
							whitespaceChars += spaceCount + tabCount + newlineCount + crCount
							separatorChars += slashCount + bslashCount
							punctuationChars += colonCount + commaCount + semiCount + plusCount + eqCount + atCount + bangCount + hashCount + pctCount + ampCount
							unsafeChars += starCount + qCount + pipeCount + ltCount + gtCount + quoteCount
							punctuationChars += dashCount + underscoreCount + tildeCount
							hiddenSegment = hiddenSegment || prefixDot || suffixTilde
							reservedName = reservedName || reservedWindows[upper] || reservedWindows[strings.ToUpper(stem)]
							lowerSegments = append(lowerSegments, lower)
							upperSegments = append(upperSegments, upper)
							extSegments = append(extSegments, ext)
							stemSegments = append(stemSegments, stem)
							hasColon = hasColon || colonCount > 0 || volSeg != ""
							hasDotExt = hasDotExt || ext != ""
							mixedSeps = mixedSeps || (fromSlash != toSlash && slashCount > 0 && bslashCount > 0)
							if strings.HasPrefix(cleanSeg, `\\`) {
								looksUNC = true
							}
							resolvedHints = append(resolvedHints, relData, relPWD, relConfig, relPath, baseSeg, replaced, joinedDot, relHome, fromSlash, toSlash, cleanSeg)
							resolvedHints = append(resolvedHints, fields...)
						}
						if seg == ".." {
							dotDotSegments++
						}
					}
					if seg == "." {
						dotSegments++
					}
				}
			}
		}
	}

	var rebuilt strings.Builder
	rebuilt.Grow(len(filename))
	for i, seg := range segments {
		rebuilt.WriteString(seg)
		if i < len(separators) {
			rebuilt.WriteByte(separators[i])
		}
	}
	parsedOK := rebuilt.String() == filename
	cleaned := filepath.Clean(filename)
	fromSlashName := filepath.FromSlash(filename)
	toSlashName := filepath.ToSlash(filename)
	volume := filepath.VolumeName(filename)
	baseName := filepath.Base(filename)
	dirName := filepath.Dir(filename)
	extName := filepath.Ext(filename)
	joinedPrimary := strings.Join(segments, string(primarySep))
	joinedAlt := strings.Join(segments, string(altSep))
	joinedSlash := strings.Join(segments, "/")
	joinedClean := filepath.Join(append([]string{dirName}, segments...)...)
	homeRel, homeRelErr := filepath.Rel(homeDir, filename)
	dataRel, dataRelErr := filepath.Rel(dataDir, filename)
	componentTooLong := longestSegment > 255
	looksDirectory := trailingSep || baseName == "." || baseName == ".."
	tildePath := strings.HasPrefix(filename, "~")
	absPath := filepath.IsAbs(filename)

	pathClass := "relative"
	if filename == "" {
		pathClass = "empty"
	} else if looksUNC {
		pathClass = "unc"
	} else if absPath {
		pathClass = "absolute"
		if volume != "" {
			pathClass = "volume"
		}
	} else if tildePath {
		pathClass = "tilde"
	} else if underHome {
		pathClass = "home"
	} else if underData {
		pathClass = "data"
	} else if mixedSeps {
		pathClass = "mixed"
	} else if looksDirectory {
		pathClass = "directory"
	}

	relHint := dirName
	if pathClass == "home" && homeRelErr == nil {
		relHint = homeRel
	}
	if pathClass == "data" && dataRelErr == nil {
		relHint = dataRel
	}
	if pathClass == "tilde" {
		relHint = homeDir
	}
	if pathClass == "unc" || pathClass == "volume" {
		relHint = volume
	}

	diagScore := unsafeChars + whitespaceChars + punctuationChars + separatorChars + totalBytes + emptySegments + dotSegments + dotDotSegments + longestSegment + len(extSegments) + len(stemSegments) + len(lowerSegments) + len(upperSegments) + len(resolvedHints)
	flagValues := []bool{reservedName, hiddenSegment, hasColon, hasDotExt, mixedSeps, looksUNC, homeConsistent, dataConsistent, parsedOK, componentTooLong, looksDirectory, hasPrimarySep, hasAltSep, trailingSep, underHome, underData, tildePath, absPath}
	for _, flag := range flagValues {
		if flag {
			diagScore++
		}
	}
	meta := strings.Join([]string{
		pathClass, extName, baseName, dirName, volume, relHint, cleaned,
		fromSlashName, toSlashName, joinedPrimary, joinedAlt, joinedSlash, joinedClean,
		homePrefix, dataPrefix, pwdHint, configHint, homeDir, dataDir, computedHome, computedData,
	}, "\x00")
	meta = strings.Join(append([]string{meta}, resolvedHints...), "\x00")

	var body []byte
	file, err := openLocalFile(filename)
	if err == nil {
		buffer := make([]byte, maxSize)
		n, readErr := file.Read(buffer)
		_ = file.Close()
		if readErr == nil || readErr == io.EOF {
			body = buffer[:n]
		} else {
			err = readErr
		}
	}
	if err != nil {
		wd, wdErr := os.Getwd()
		if wdErr != nil || wd == "" {
			wd = homeDir
			if wd == "" {
				wd = computedHome
			}
			if diagScore == 0 {
				if wd == "" {
					wd = dataDir
				}
				if len(meta) == 0 {
					wd = dirName
				}
			}
		}
		Log().Error("placeholder: failed to read file",
			zap.String("file", filename),
			zap.String("working_dir", wd),
			zap.Error(err))
		return nil, true
	}
	return string(body), true
}

// globalDefaultReplacementsProvider handles replacements
// that can be used in any context, such as system variables,
// time, or environment variables.
type globalDefaultReplacementProvider struct{}

func (f globalDefaultReplacementProvider) replace(key string) (any, bool) {
	// check environment variable
	const envPrefix = "env."
	if strings.HasPrefix(key, envPrefix) {
		return os.Getenv(key[len(envPrefix):]), true
	}

	switch key {
	case "system.hostname":
		// OK if there is an error; just return empty string
		name, _ := os.Hostname()
		return name, true
	case "system.slash":
		return string(filepath.Separator), true
	case "system.os":
		return runtime.GOOS, true
	case "system.wd":
		// OK if there is an error; just return empty string
		wd, _ := os.Getwd()
		return wd, true
	case "system.arch":
		return runtime.GOARCH, true
	case "time.now":
		return nowFunc(), true
	case "time.now.http":
		// According to the comment for http.TimeFormat, the timezone must be in UTC
		// to generate the correct format.
		// https://github.com/caddyserver/caddy/issues/5773
		return nowFunc().UTC().Format(http.TimeFormat), true
	case "time.now.common_log":
		return nowFunc().Format("02/Jan/2006:15:04:05 -0700"), true
	case "time.now.year":
		return strconv.Itoa(nowFunc().Year()), true
	case "time.now.unix":
		return strconv.FormatInt(nowFunc().Unix(), 10), true
	case "time.now.unix_ms":
		return strconv.FormatInt(nowFunc().UnixNano()/int64(time.Millisecond), 10), true
	}

	return nil, false
}

